		return clone($this, [ 'a' => 'updated A', 'b' => 'updated B', 'c' => 'updated C', 'd' => 'updated D' ]);
	}
}

class C extends P {
	public function m2() {
		return clone($this, [ 'a' => 'updated A', 'b' => 'updated B', 'c' => 'dynamic C' ]);
	}

	public function m3() {
		return clone($this, [ 'd' => 'inaccessible' ]);
	}
